    j = 0
    for i in range(N):
        target = 2 * A[i]
        if j < i:
            j = i
        while j < N and A[j] < target:
            j += 1
        f[i] = j

    h = [f[i] - i for i in range(N)]

    st = [h]
    length = 1
    while length * 2 <= N:
        prev = st[-1]
        cur_len = N - 2 * length + 1
        cur = [0] * cur_len
        for i in range(cur_len):
            cur[i] = max(prev[i], prev[i + length])
        st.append(cur)
        length *= 2

    def range_max(l, r):
        if l > r:
            return -1
        k = (r - l + 1).bit_length() - 1
        size = 1 << k
        return max(st[k][l], st[k][r - size + 1])

    ans = []
    for _ in range(Q):
        L = int(data[idx]) - 1
        R = int(data[idx + 1]) - 1
        idx += 2

        n = R - L + 1
        lo, hi = 0, n // 2

        while lo < hi:
            mid = (lo + hi + 1) // 2
            if range_max(L, L + mid - 1) <= n - mid:
                lo = mid
            else:
                hi = mid - 1

        ans.append(str(lo))

    sys.stdout.write("\n".join(ans))

